    var currentUser = HttpContext.User;
    Users myuser = GameHelpers.GetUserByContext(currentUser, _context);
    bool addpoints = false;
    if (myuser != null)
    {
        var userAnswer = _context.Reviews.Where(a => a.StageId == answer.parentId && a.UserId == myuser.Id.ToString()).FirstOrDefault();
        if (userAnswer != null)
        {
            userAnswer.Answer = answer.answer;
            if (userAnswer.Answer.Length < 20 && answer.answer.Length > 20)
            {
                addpoints = true;
            }

        }
        else
        {
            if (answer.answer.Length > 20)
            {
                addpoints = true;
            }
            userAnswer = new Reviews();
            userAnswer.StageId = answer.parentId;

            userAnswer.UserId = myuser.Id.ToString();
            userAnswer.Answer = answer.answer;
            _context.Reviews.Add(userAnswer);
        }
        if (addpoints)
        {
            Stages stage = _context.Stages.Where(a => a.Id.ToString() == answer.parentId).FirstOrDefault();
            Actions action = _context.Actions.Where(a => a.Id.ToString() == stage.ParentId).FirstOrDefault();
            var stagescount = _context.Stages.Where(a => a.ParentId == stage.ParentId).Count();
            List<ActionToStatesDefs> stateDefs = _context.ActionToStatesDefs.Where(a => a.ActionId == action.Id.ToString()).ToList();
            foreach (ActionToStatesDefs statedef in stateDefs)
            {
                UsersStates userstates = new UsersStates();
                userstates.ActionId = statedef.ActionId;
                if (stagescount > 1)
                    userstates.Points = statedef.Addition / stagescount;
                else
                    userstates.Points = statedef.Addition;
                userstates.UserId = myuser.Id.ToString();
                userstates.StateId = statedef.StateId;
                userstates.Updated = DateTime.Now;
                userstates.CardId = action.ParentId;
                userstates.Explanation = action.Title;
                _context.UsersStates.Add(userstates);
            }
        }
        _context.SaveChanges();
        response = Ok(new { answerId = userAnswer.Id });
    }

    return response;

